parameters.jsCode:
// Prepare Python breeding call
const parentMaps = $input.all().slice(0, -2).map(i => i.json.map_json);
const breedingConfig = $input.all().slice(-1)[0].json;
const tendrils = $input.first().json;

const pythonCode = `
import sys
import json
sys.path.append('/home/user/higgs-universal-memory-contract')
from slimemold_breeding_engine import breed_variants

parent_maps = ${JSON.stringify(parentMaps)}
breeding_config = ${JSON.stringify(breedingConfig)}
generation = ${tendrils.generation + 1}

offspring = breed_variants(parent_maps, breeding_config, generation)
print(json.dumps(offspring))
`;

return {
  python_code: pythonCode,
  tendril_key: tendrils.tendril_key,
  generation: tendrils.generation + 1
};

// Parse offspring from Python output
const output = $input.first().json.stdout;
const offspring = JSON.parse(output);

const tendrils = $input.all()[1].json;

return offspring.map(variant => ({
  json: {
    ...variant,
    tendril_key: tendrils.tendril_key
  }
}));

parameters.query:
-- Prune poor performers
SELECT prune_poor_performers(
  $1::TEXT,    -- tendril_key
  $2::NUMERIC, -- bottom_percentile
  $3::INT      -- min_sample_size
) AS pruned_count;

parameters.jsCode:
// Evaluate promotion candidates
const items = $input.all();
const promotions = [];

for (const item of items) {
  const data = item.json;

  // Get control variant (current production) fitness
  // TODO: Query control variant fitness
  const controlFitness = 100; // Placeholder

  const lift = ((data.fitness_score - controlFitness) / controlFitness) * 100;

  if (lift >= data.min_lift_needed) {
    promotions.push({
      deployment_id: data.deployment_id,
      variant_id: data.variant_id,
      tendril_key: data.tendril_key,
      conclusion: 'promote',
      lift_vs_control: lift.toFixed(2),
      decided_by: 'organism_auto',
      decision_notes: `Fitness score ${data.fitness_score.toFixed(2)} exceeds control by ${lift.toFixed(1)}%`
    });
  }
}

return promotions.map(p => ({ json: p }));

// Emit summary
const items = $input.all();

const summary = {
  run_timestamp: new Date().toISOString(),
  evolutionary_tendrils_processed: items.length,
  offspring_generated: items.reduce((sum, i) => sum + (i.json.offspring_count || 0), 0),
  variants_pruned: items.reduce((sum, i) => sum + (i.json.pruned_count || 0), 0),
  variants_promoted: items.reduce((sum, i) => sum + (i.json.promoted_count || 0), 0)
};

console.log('🧬 Evolutionary loop summary:', JSON.stringify(summary, null, 2));

return { json: summary };
